import pysam

vcf = pysam.VariantFile("all_samples.vcf.gz")
samples = list(vcf.header.samples)
print("Samples:", samples)

tumours = ["CG24-4187", "CG24-7410", "CG24-9024"]
normals = ["CG24-1366", "CG24-3973", "CG24-6425"]

# Count matching genotypes at sites where normal has QUAL > 30 and DP >= 20
matches = {t: {n: 0 for n in normals} for t in tumours}
totals = {t: {n: 0 for n in normals} for t in tumours}

for rec in vcf:
